var q = new BlockingCollection<Request>(new ConcurrentQueue<Request>(), 1024);
var workers = Enumerable.Range(0, 4).Select(_ => new Thread(() => {
    foreach (var req in q.GetConsumingEnumerable()) Handle(req);     // blocks
})).ToArray();
foreach (var w in workers) w.Start();
